{
 "content": "def transform(grid):
    # The demonstrated operation converts an outlined square/shape into
    # an open, slanted contour while leaving the lower edge in place.
    out = [[0 for _ in row] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    color = grid[r0][next(c for c in range(c0, c1 + 1) if grid[r0][c])]
    # Preserve the bottom boundary; push the contour from the upper
    # boundary into a descending diagonal on both sides.
    for c in range(c0, c1 + 1):
        if grid[r1][c] == color:
            out[r1][c] = color
    # Upper boundary is shortened and shifted left by its height.
    top = [c for c in range(c0, c1 + 1) if grid[r0][c] == color]
    for c in top[:max(1, len(top) - 2)]:
        nc = c - (c1 - c0)
        if nc >= 0:
            out[r0][nc] = color
    # Vertical contours descend diagonally.
    for k, r in enumerate(range(r0 + 1, r1)):
        if grid[r][c0] == color:
            nc = c0 - (r - r0)
            if 0 <= nc < len(out[r]):
                out[r][nc] = color
        if grid[r][c1] == color:
            nc = c0 + (r - r0)
            if 0 <= nc < len(out[r]):
                out[r][nc] = color
    return out
