    color = grid[r0][next(c for c in range(c0,c1+1) if grid[r0][c])]
    # Keep the bottom bar and bend the two side walls into diagonals.
    for c in range(c0,c1+1):
        if grid[r1][c] == color:
            out[r1][c] = color
    # The original top edge moves to the leftmost visible position.
    for c in range(c0,c1+1):
        if grid[r0][c] == color:
            nc = max(0, c - (c1-c0))
            out[r0][nc] = color
    for r in range(r0+1,r1):
        if grid[r][c0] == color:
            nc = c0 - (r-r0)
            if 0 <= nc < len(out[r]):
                out[r][nc] = color
        if grid[r][c1] == color:
            nc = c0 + (r-r0)
            if 0 <= nc < len(out[r]):
                out[r][nc] = color
    return out
