 "content": "def transform(grid):
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    color = grid[r0][next(c for c in range(c0, c1 + 1) if grid[r0][c])]
    out = [[0] * len(row) for row in grid]
    # Demo's rectangular frame becomes a stepped, diagonally folded left
    # wall, with its bottom edge retained.
    if all(grid[r0][c] == color for c in range(c0, c1 + 1)) and all(grid[r1][c] == color for c in range(c0, c1 + 1)):
        w, h = c1 - c0 + 1, r1 - r0 + 1
        # Compress the top side into a short horizontal run at the left.
        for c in range(c0, min(c0 + 3, c1 + 1)):
            out[r0][c - c0] = color
        # Left wall folds into a descending diagonal from upper-right
        # to lower-left, ending at the left edge of the retained base.
        for k in range(1, min(h - 1, w - 1)):
            r, c = r0 + k, c0 + (3 - k)
            if 0 <= c < len(out[r]):
                out[r][c] = color
        for k in range(1, min(h - 1, w - 1)):
            r, c = r0 + k, c0 - (k - 1)
            if 0 <= c < len(out[r]):
                out[r][c] = color
        for c in range(c0, c1 + 1):
            out[r1][c] = color
        return out
    return [row[:] for row in grid]
