 "content": "def transform(grid):
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not cells:
        return [row[:] for row in grid]
    top = min(r for r, c, v in cells)
    bottom = max(r for r, c, v in cells)
    left = min(c for r, c, v in cells)
    right = max(c for r, c, v in cells)
    color = cells[0][2]
    out = [[0] * len(row) for row in grid]
    # The frame's top edge shifts to the far left, then successive side
    # points form a diagonal fan; its base remains in place.
    for c in range(left, right + 1):
        if grid[top][c] == color:
            out[top][c - left] = color
        if grid[bottom][c] == color:
            out[bottom][c] = color
    # Left vertical side folds diagonally toward the left edge.
    for r in range(top + 1, bottom):
        if grid[r][left] == color:
            c = left - (r - top)
            if 0 <= c < len(out[r]):
                out[r][c] = color
    # Right side is a diagonal that advances left one cell each row.
    for r in range(top + 1, bottom):
        if grid[r][right] == color:
            c = right - (r - top)
            if 0 <= c < len(out[r]):
                out[r][c] = color
    return out
