{
 "content": "def transform(grid):
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not cells:
        return [row[:] for row in grid]
    top = min(r for r, c, v in cells)
    bottom = max(r for r, c, v in cells)
    left = min(c for r, c, v in cells)
    right = max(c for r, c, v in cells)
    color = cells[0][2]
    out = [[0] * len(row) for row in grid]
    # Top and bottom bars form the two horizontal ends of the fan.
    for c in range(left, right + 1):
        if grid[top][c] == color:
            nc = c - left
            out[top][nc] = color
        if grid[bottom][c] == color:
            out[bottom][c] = color
    # Both vertical frame sides fold toward the center as diagonals.
    for r in range(top + 1, bottom):
        if grid[r][left] == color:
            nc = left - (r - top)
            if 0 <= nc < len(out[r]):
                out[r][nc] = color
        if grid[r][right] == color:
            nc = right - (r - top)
            if 0 <= nc < len(out[r]):
                out[r][nc] = color
    return out
",
