 "content": "def transform(grid):
    # Redraw the frame as its left-leaning diagonal counterpart.
    cells=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    if not cells:return [row[:] for row in grid]
    top=min(r for r,c,v in cells); bottom=max(r for r,c,v in cells)
    color=cells[0][2]
    out=[[0]*len(row) for row in grid]
    # Three-cell cap, then a one-cell diagonal, followed by parallel
    # diagonal rails; bottom bar anchors the transformed shape.
    pattern={top:[0,1,2], top+1:[3], top+2:[0,4], top+3:[1,5]}
    for r,cols in pattern.items():
        if 0<=r<len(out):
            for c in cols:
                if c<len(out[r]):out[r][c]=color
    # bottom edge copied from the input
    for c,v in enumerate(grid[bottom]):
        if v:out[bottom][c]=v
    return out
