    cells = [(r, c, value) for r, row in enumerate(grid) for c, value in enumerate(row) if value != 0]
    if not cells:
        return [row[:] for row in grid]

    top = min(r for r, c, value in cells)
    bottom = max(r for r, c, value in cells)
    left = min(c for r, c, value in cells)

    color = cells[0][2]
    out = [[0] * len(row) for row in grid]

    # The top three cells move to the left margin. The outline's sides
    # become the diagonal stair-step motif; its bottom edge stays fixed.
    pattern = {
        0: [0, 1, 2],
        1: [3],
        2: [0, 4],
        3: [1, 5],
    }
    for dr, cols in pattern.items():
        r = top + dr
        if r < bottom:
            for c in cols:
                if c < len(out[r]):
                    out[r][c] = color

    for r, c, value in cells:
        if r == bottom:
            out[r][c] = value

    return out
